python3 -c "
import json;d=json.load(open('/tmp/cala_openapi.json'))
comp=d.get('components',{}).get('schemas',{})
def deref(s):
    if '\$ref' in s: return s['\$ref'].split('/')[-1]
    return s
for p,ops in d['paths'].items():
    for m,op in ops.items():
        print('==',m.upper(),p)
        for prm in op.get('parameters',[]):
            print('   param:',prm['name'],prm.get('required'),json.dumps(prm.get('schema',{}))[:120])
        rb=op.get('requestBody')
        if rb:
            sch=list(rb['content'].values())[0]['schema']
            print('   body:',deref(sch))
print()
for n,s in comp.items():
    if 'Request' in n or 'Retrieval' in n or 'Query' in n:
        print('###',n, json.dumps(s.get('properties',{}))[:700])
"

