<script>
  const stages = [...document.querySelectorAll('.stage')];
  const rail = document.querySelector('.rail');
  const hint = document.getElementById('hint');
  let i = 0;

  stages.forEach((s, n) => {
    const b = document.createElement('button');
    b.type = 'button';
    b.setAttribute('aria-label', 'Step ' + (n + 1) + ' of ' + stages.length);
    b.innerHTML = '<i></i>';
    b.addEventListener('click', (e) => { e.stopPropagation(); show(n); });
    rail.appendChild(b);
  });
  const dots = [...rail.children];

  function show(n) {
    i = Math.max(0, Math.min(stages.length - 1, n));
    stages.forEach((s, k) => { s.hidden = k !== i; });
    // re-trigger the entrance animation
    const cur = stages[i];
    cur.querySelectorAll(':scope > *').forEach((el) => {
      el.style.animation = 'none'; void el.offsetWidth; el.style.animation = '';
    });
    document.body.style.setProperty('--ground', cur.dataset.ground);
    document.body.style.setProperty('--ink', cur.dataset.ink);
    document.body.classList.toggle('filed', cur.dataset.filed === '1');
    dots.forEach((d, k) => d.setAttribute('aria-current', String(k === i)));
    hint.textContent = i === stages.length - 1 ? 'that is the whole chain'
                                               : 'click to descend';
    window.scrollTo({ top: 0 });
  }

  const advance = () => show(i + 1 >= stages.length ? 0 : i + 1);
  document.addEventListener('click', (e) => { if (!e.target.closest('a,button')) advance(); });
  document.addEventListener('keydown', (e) => {
    if ([' ', 'ArrowDown', 'ArrowRight', 'Enter'].includes(e.key)) { e.preventDefault(); advance(); }
    if (['ArrowUp', 'ArrowLeft'].includes(e.key)) { e.preventDefault(); show(i - 1); }
  });
  show(0);
</script>
