body { overflow-x:hidden; overflow-y:auto; }
.response-panel pre { max-height:26rem; }

/* ---------------------------------------------------------------- the dig */
.dig, .result { width:min(46rem,92vw); margin:0 auto; padding:0 0 3rem; }
.dig[hidden], .result[hidden] { display:none; }

.chain { list-style:none; margin:1.4rem 0 0; padding:0; }
.chain li {
  position:relative; padding:1rem 0 1rem 1.9rem; border-left:1px solid var(--line);
  animation:rise .5s cubic-bezier(.2,.7,.3,1) both;
}
.chain li::before {
  content:""; position:absolute; left:-4.5px; top:1.45rem;
  width:8px; height:8px; border-radius:50%; background:var(--ink);
}
.chain li[data-provisional="true"] { border-left-style:dashed; opacity:.62; }
.chain li[data-provisional="true"]::before { background:none; border:1px solid var(--ink); }
.chain li[data-terminal="true"]::before { background:var(--candy); box-shadow:0 0 0 4px rgba(196,52,42,.15); }
@keyframes rise { from { opacity:0; transform:translateY(14px); } to { opacity:1; transform:none; } }

.chain__step { font-family:var(--mono); font-size:.64rem; letter-spacing:.18em;
  text-transform:uppercase; opacity:.5; margin:0 0 .3rem; }
.chain__name { font-family:var(--mono); font-size:1.02rem; line-height:1.35; margin:0; }
.chain__name[data-human="true"] { font-family:var(--serif); font-size:1.3rem; font-weight:600; }
.chain__meta { font-family:var(--mono); font-size:.78rem; line-height:1.7; opacity:.66; margin:.35rem 0 0; }
.chain__addr { font-family:var(--mono); font-size:.9rem; line-height:1.5; margin:.5rem 0 0; }

.probe { display:flex; gap:.7rem; align-items:baseline; font-family:var(--mono);
  font-size:.76rem; opacity:.6; margin:1rem 0 0; padding-left:1.9rem; }
.probe__t { opacity:.6; font-variant-numeric:tabular-nums; }
.probe__q::after { content:"…"; }

/* silence, with the ladder that proves it */
.gap { border:1px solid var(--line); padding:1rem 1.1rem; margin:1.2rem 0 0 1.9rem;
  font-family:var(--mono); font-size:.82rem; }
.gap b { font-weight:500; color:var(--candy); }
.gap ul { margin:.6rem 0 0; padding-left:1.1rem; opacity:.6; font-size:.74rem; line-height:1.8; }

/* -------------------------------------------------------------- the result */
.score { display:flex; flex-wrap:wrap; gap:2.2rem; margin:0 0 2.4rem; }
.score div b { display:block; font-family:var(--serif); font-size:2.6rem; font-weight:400;
  letter-spacing:-.03em; line-height:1; }
.score div span { font-family:var(--mono); font-size:.66rem; letter-spacing:.1em;
  text-transform:uppercase; opacity:.6; }
.score .hot b { color:var(--candy); }

.concern { border:1px solid var(--line); padding:1.1rem 1.2rem; margin:0 0 .9rem; }
.concern[data-status="found"] { border-color:var(--candy); }
.concern__head { display:flex; justify-content:space-between; gap:1rem; align-items:baseline;
  font-family:var(--mono); font-size:.7rem; letter-spacing:.14em; text-transform:uppercase; }
.concern[data-status="found"] .concern__head { color:var(--candy); }
.concern__flag { margin:.8rem 0 0; }
.concern__about { font-family:var(--mono); font-size:.72rem; letter-spacing:.06em;
  background:var(--ink); color:var(--paper); padding:.14rem .42rem; }
.concern__title { font-size:1rem; line-height:1.45; margin:.4rem 0 0; }
.concern__sum { font-family:var(--mono); font-size:.76rem; line-height:1.6; opacity:.66; margin:.25rem 0 0; }
.concern__note { font-family:var(--mono); font-size:.74rem; line-height:1.6; opacity:.6; margin:.7rem 0 0; }

.story { list-style:none; margin:2.6rem 0 0; padding:0; }
.story li { padding:.9rem 0; border-top:1px solid var(--line); }
.story li:first-child { border-top:0; }
.story__kind { font-family:var(--mono); font-size:.62rem; letter-spacing:.18em;
  text-transform:uppercase; opacity:.45; }
.story__head { font-size:1.06rem; line-height:1.45; margin:.3rem 0 0; }
.story li[data-weight="high"] .story__head { font-size:1.5rem; font-weight:600; letter-spacing:-.01em; }
.story li[data-kind="concern"][data-weight="high"] .story__head { color:var(--candy); }
.story__detail { font-family:var(--mono); font-size:.78rem; line-height:1.65; opacity:.62; margin:.3rem 0 0; }

.sources { margin:2.6rem 0 0; font-family:var(--mono); font-size:.78rem; }
.sources summary { cursor:pointer; opacity:.6; }
.sources__list { margin:.9rem 0 0; padding-left:1.1rem; line-height:1.9; }
.sources__list a { color:var(--ink); }
#again { margin-top:2.4rem; }

