<script>
  const cards = [...document.querySelectorAll('.card')];
  const spine = document.getElementById('spine');
  const hint = document.getElementById('hint');
  const bet = { own:null, steps:null, brands:0 };
  let i = 0;

  cards.forEach(() => spine.appendChild(document.createElement('i')));
  const pips = [...spine.children];

  const OWNED = ['Kinder','Ferrero Rocher','Tic Tac','Keebler','Special K','Rice Krispies'];
  const OTHER = ['Oreo','KitKat','M&M’s','Toblerone','Snickers','Haribo'];
  const grid = document.getElementById('grid');
  [...OWNED, ...OTHER].sort(() => Math.random() - .5).forEach((name) => {
    const b = document.createElement('button');
    b.type = 'button'; b.className = 'brand'; b.textContent = name;
    b.dataset.own = OWNED.includes(name) ? '1' : '0';
    b.setAttribute('aria-pressed','false');
    b.addEventListener('click', (e) => {
      e.stopPropagation();
      b.setAttribute('aria-pressed', b.getAttribute('aria-pressed') === 'true' ? 'false' : 'true');
    });
    grid.appendChild(b);
  });

  const countUp = (el, to, dp = 0) => {
    const t0 = performance.now(), dur = 1100;
    const tick = (t) => {
      const p = Math.min(1, (t - t0) / dur);
      const e = 1 - Math.pow(1 - p, 3);
      el.textContent = (to * e).toFixed(dp) + (dp ? 's' : '');
      if (p < 1) requestAnimationFrame(tick);
      else el.textContent = (dp ? to.toFixed(1) + 's' : to.toLocaleString('en-US'));
    };
    requestAnimationFrame(tick);
  };

  function show(n) {
    i = Math.max(0, Math.min(cards.length - 1, n));
    cards.forEach((c, k) => { c.hidden = k !== i; });
    pips.forEach((p, k) => p.classList.toggle('on', k <= i));
    const cur = cards[i];
    cur.querySelectorAll(':scope > *').forEach((el) => {
      el.style.animation = 'none'; void el.offsetWidth; el.style.animation = '';
    });
    cur.querySelectorAll('.t').forEach((el) => countUp(el, parseFloat(el.dataset.to), 1));
    const big = cur.querySelector('[data-count]');
    if (big) countUp(big, parseInt(big.dataset.count, 10));
    const kind = cur.dataset.kind;
    hint.textContent = (kind === 'bet' || kind === 'bet2') ? 'choose one'
      : kind === 'game' ? 'tap, then reveal'
      : kind === 'verdict' ? '' : 'click anywhere to continue';
  }

  const gate = () => ['bet','bet2','game','verdict'].includes(cards[i].dataset.kind);
  document.addEventListener('click', (e) => {
    if (e.target.closest('a,button')) return;
    if (gate()) return;
    show(i + 1);
  });
  document.addEventListener('keydown', (e) => {
    if (e.key === ' ' || e.key === 'ArrowRight') { if (!gate()) { e.preventDefault(); show(i + 1); } }
    if (e.key === 'ArrowLeft') { e.preventDefault(); show(i - 1); }
  });

  document.querySelectorAll('[data-bet]').forEach((b) => b.addEventListener('click', () => {
    bet.own = b.dataset.bet; show(i + 1);
  }));
  document.querySelectorAll('[data-bet2]').forEach((b) => b.addEventListener('click', () => {
    bet.steps = b.dataset.bet2; show(i + 1);
  }));

  document.getElementById('reveal').addEventListener('click', () => {
    document.body.classList.add('revealed');
    bet.brands = [...grid.children]
      .filter((b) => b.dataset.own === '1' && b.getAttribute('aria-pressed') === 'true').length;
    document.getElementById('gameSay').textContent =
      `You spotted ${bet.brands} of 6. The four cereals are Ferrero's too.`;
    const btn = document.getElementById('reveal');
    btn.textContent = 'Continue'; btn.onclick = () => show(i + 1);
  });

  document.getElementById('again').addEventListener('click', () => {
    document.body.classList.remove('revealed');
    [...grid.children].forEach((b) => b.setAttribute('aria-pressed','false'));
    document.getElementById('reveal').textContent = 'Reveal';
    document.getElementById('reveal').onclick = null;
    bet.own = bet.steps = null; bet.brands = 0;
    show(0);
  });

  // fill the verdict as it opens
  const obs = new MutationObserver(() => {
    const v = cards.find((c) => c.dataset.kind === 'verdict');
    if (v.hidden) return;
    const rightOwn = bet.own === 'yes';           // it really is still Italian-owned
    const rightSteps = bet.steps === '1-2';       // two steps
    document.getElementById('vOwn').textContent = bet.own === 'yes' ? 'Italy' : 'Elsewhere';
    document.getElementById('vSteps').textContent = bet.steps || '—';
    document.getElementById('vBrands').textContent = bet.brands + '/6';
    const score = (rightOwn ? 1 : 0) + (rightSteps ? 1 : 0) + (bet.brands >= 4 ? 1 : 0);
    document.getElementById('vWord').textContent = score >= 2 ? 'close' : 'wrong';
    document.getElementById('vSay').textContent = rightOwn
      ? 'You were right about the country — and that is the rare one. Most things on a shelf have left home. What you almost certainly missed is the shelf itself: ninety-four brands end at the same family.'
      : 'It is still Italian, and privately held by one family — which is unusual. Most things on a shelf have left home. Ninety-four brands end at this one.';
  });
  obs.observe(document.getElementById('deck'), { attributes:true, subtree:true, attributeFilter:['hidden'] });

  show(0);
</script>
